```php
<?php
session_start();

// Rialaitheadh an t-aistriú
if (!isset($_SESSION['user_id'])) {
  header("Location: login.php");
  exit();
}

// Réadmhaireacht a roinnt
$user_id = $_SESSION['user_id'];

// Ceannothú úsáideora
if (isset($_GET['logout'])) {
  session_destroy();
  header("Location: login.php");
  exit();
}

// Príomhú lárscríbhinn
if (isset($_POST['submit'])) {
  $message = $_POST['message'];

  // Príomhú lárscríbhinn
  if (!empty($message)) {
    // Tá an lárscríbhinn ar fáil, an chéad uair a fhéadfaidh sé a cheiltíonn.
    if (!isset($_SESSION['messages'])) {
      $_SESSION['messages'] = array();
    }

    // Tá lárscríbhinn anseo, an chéad uair a fhéadfaidh sé a cheiltíonn.
    $_SESSION['messages'][] = array(
      'id' => rand(100000, 999999), // ID a theip ar an lárscríbhinn
      'user_id' => $user_id,
      'message' => $message,
      'timestamp' => time()
    );

    // An lárscríbhinn cheiltíonn
    if (ceiltíonnLáithreachtMailíseach($user_id, $message));
  }
}

// Ceannothú lárscríbhinn
if (isset($_GET['view'])) {
  $message_id = $_GET['view'];

  // Ceannothú lárscríbhinn
  if (ceiltíonnLáithreachtMailíseach($user_id, $message_id));
}

// Cúpla lárscríbhinn
if (isset($_SESSION['messages'])) {
  $messages = $_SESSION['messages'];
  usort($messages, function($a, $b) {
